import kotlin.math.*

@OptIn(ExperimentalUnsignedTypes::class)
fun main() {
    println("== floorDiv / mod")
    println((-7).floorDiv(2.toByte()))
    println((-7).floorDiv(2.toShort()))
    println((-7).mod(3.toByte()))
    println((-7).mod(3.toShort()))
    println((-7).mod(3L))
    println((-7L).floorDiv(2.toByte()))
    println((-7L).floorDiv(2.toShort()))
    println((-7L).mod(3.toByte()))
    println((-7L).mod(3.toShort()))
    println("== math")
    println(max(3u, 5u))
    println(min(3u, 5u))
    println(max(3uL, 5uL))
    println(min(3uL, 5uL))
    println(sign(-2.5f))
    println(sign(0f))
    println(sign(2.5f))
    println("== zip")
    val u = uintArrayOf(1u, 2u, 3u)
    println(u.zip(arrayOf("a", "b")))
    println(u.zip(listOf("a", "b", "c", "d")))
    println(u.zip(arrayOf("a", "b")) { x, y -> "$x$y" })
    println(u.zip(listOf("a", "b", "c", "d")) { x, y -> "$x$y" })
    println(ubyteArrayOf(1u, 2u).zip(listOf(5, 6)) { x, y -> x.toInt() + y })
    println(ushortArrayOf(1u, 2u).zip(arrayOf(5, 6)) { x, y -> x.toInt() + y })
    println(ulongArrayOf(1u, 2u).zip(listOf(5, 6)) { x, y -> x.toLong() + y })
    println("== misc")
    println(listOf(1, 2, 3, 4, 5).slice(1..3))
    println(Char(65u.toUShort()))
    println(1.compareTo(2L))
    println(1.0.compareTo(1))
    println(2L.compareTo(1.5f))
    println(1.toByte().compareTo(1.toShort()))
    println(3u.compareTo(2uL))
    println(true.compareTo(false))
    println('a'.compareTo('b'))
    println("hello".replaceAfter('l', "X"))
    println("hello".replaceAfterLast('l', "X"))
    println("hello".replaceBefore('l', "X"))
    println("hello".replaceBeforeLast('l', "X"))
    println("hello".replaceRange(1, 3, "YY"))
    println("hello".replaceRange(1..2, "YY"))
    println("hello".startsWith("el", 1))
    println("hello".startsWith("EL", 1, true))
    println("hello".removePrefix("he" as CharSequence))
    println("hello".removeSuffix("lo" as CharSequence))
    println("[hello]".removeSurrounding("[" as CharSequence, "]" as CharSequence))
    println("'hello'".removeSurrounding("'" as CharSequence))
    println("hello".subSequence(1, 3))
    val sb = StringBuilder()
    sb.append(1.toByte()).append(2.toShort()).append(null as Any?).append("x" as Any)
    sb.appendRange("abcdef", 1, 3).appendRange(charArrayOf('x', 'y', 'z'), 0, 2)
    sb.insertRange(0, "QRS", 1, 2).insertRange(1, charArrayOf('7', '8', '9'), 1, 3)
    println(sb)
}
